import math

def is_prime(k):
    if k <= 1:
        return False
    if k <= 3:
        return True
    if k % 2 == 0 or k % 3 == 0:
        return False
    i = 5
    while i * i <= k:
        if k % i == 0 or k % (i + 2) == 0:
            return False
        i += 6
    return True

def check_integer(n):
    if n < 0:
        return False, None

    denominator = 2 * n - 1
    if denominator == 0: # Should not happen for n>=0, but good practice
        return False, None 

    try:
        # Calculate (n+2)! + 1
        # Use math.factorial for large factorials
        n_plus_2_factorial = math.factorial(n + 2)
        numerator_term = 3 * (n_plus_2_factorial + 1)

        # Check divisibility
        if numerator_term % denominator == 0:
            result = numerator_term // denominator
            return True, result
        else:
            return False, None
    except OverflowError:
        # This should not happen with standard Python integers, but as a safeguard
        return False, None

# Test range up to n=40
N_MAX = 40
solutions = []
primes_checked = []

print("--- Testing all n up to 40 ---")
for n in range(N_MAX + 1):
    is_int, value = check_integer(n)
    if is_int:
        solutions.append(n)
        print(f"n={n}: Solution found. Value: {value}")
    # Optional: print non-solutions for context, but let's keep output clean

print("\n--- Checking targeted primes (2n-1 > 23) ---")
for n in range(N_MAX + 1):
    denominator = 2 * n - 1
    if denominator > 23 and is_prime(denominator):
        primes_checked.append(n)
        is_int, _ = check_integer(n)
        if is_int:
            print(f"n={n} (2n-1={denominator}): Solution found via prime denominator.")
        else:
            print(f"n={n} (2n-1={denominator}): Not a solution.")

print("\n--- Summary ---")
print(f"Solutions found up to n={N_MAX}: {solutions}")

